#[derive(Default)]
pub struct DeclarationSource {
    pub records: std::collections::BTreeMap<u32, serde_json::Value>,
    pub requests: Vec<String>,
}

pub async fn start_declaration_source(
    source: std::sync::Arc<std::sync::Mutex<DeclarationSource>>,
) -> anyhow::Result<(super::Guard, String)> {
    use axum::{Json, Router, extract::{OriginalUri, State}};
    type Source = std::sync::Arc<std::sync::Mutex<DeclarationSource>>;
    async fn interests(State(source): State<Source>, OriginalUri(uri): OriginalUri) -> Json<serde_json::Value> {
        let mut source = source.lock().unwrap();
        source.requests.push(uri.to_string());
        let url = reqwest::Url::parse(&format!("http://localhost{uri}")).unwrap();
        let query = url.query_pairs().into_owned().collect::<std::collections::BTreeMap<_, _>>();
        let discovery = query.contains_key("PublishedFrom") || query.contains_key("UpdatedFrom");
        let items = source.records.iter().filter(|(id, _)| {
            if let Some(id_requested) = query.get("InterestIds") {
                id.to_string() == *id_requested
            } else if let Some(member) = query.get("MemberId") {
                member == "1"
            } else if query.contains_key("PublishedFrom") {
                **id == 3
            } else {
                **id == 1
            }
        }).map(|(_, record)| {
            let mut record = record.clone();
            if discovery {
                // Discovery carries only an older version; hydration must replace it.
                record["versions"] = serde_json::json!([record["versions"].as_array().unwrap().last().unwrap()]);
            }
            record
        }).collect::<Vec<_>>();
        let total = items.len();
        let skip = query["Skip"].parse::<usize>().unwrap();
        let take = query["Take"].parse::<usize>().unwrap();
        Json(serde_json::json!({"totalResults": total, "items": items.into_iter().skip(skip).take(take).collect::<Vec<_>>()}))
    }
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await?;
    let port = listener.local_addr()?.port();
    let app = Router::new().route("/Interests", axum::routing::get(interests)).with_state(source);
    let server = tokio::spawn(async move { axum::serve(listener, app).await.unwrap(); });
    Ok((super::Guard { port, server }, format!("http://127.0.0.1:{port}/Interests")))
}
